import type { OrgId } from "@/types/common";
import type { Subscription, WorkspaceLockReason } from "@/types/billing";

/**
 * Thrown by `assertWorkspaceWritable()`; mapped to a `plan_limit_exceeded`
 * `ActionResult` by `toAppError()`.
 */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is locked (${reason}) and cannot be modified until billing is resolved.`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * The pure lock rule, evaluated at `now` against the subscription as stored.
 *
 * No subscription row, or an `active` one, is writable. `past_due` is always
 * locked. `trialing` locks once the current period end is reached. `canceled`
 * locks once its cancellation date is reached — a `cancelAt` in the future
 * keeps it writable until then, and no `cancelAt` counts as canceled now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return now.getTime() >= new Date(subscription.currentPeriodEnd).getTime()
        ? "trial_ended"
        : null;
    case "canceled": {
      const cancelAt = subscription.cancelAt;
      if (cancelAt === null) return "canceled";
      return now.getTime() >= new Date(cancelAt).getTime() ? "canceled" : null;
    }
  }
}

